// std::unique_ptr: Exclusive ownership, RAII guarantee

struct HeavyResource { ~HeavyResource() {} };

// Preferred creation (exception safety)
auto ptr1 = std::make_unique<HeavyResource>();

// Unique ownership means non-copyable
// auto ptr2 = ptr1; // ERROR

// Ownership must be moved
auto ptr3 = std::move(ptr1);

// Access raw pointer (use only when necessary)
HeavyResource* raw = ptr3.get();
ptr3.reset(); // Explicitly releases resource now



// std::shared_ptr: Shared ownership, reference counting

struct SharedData {};

// Preferred creation
auto sp1 = std::make_shared<SharedData>(); // Count = 1

// Copying shares ownership
auto sp2 = sp1; // Count = 2

// Access count
int c = sp2.use_count(); // c == 2

// Access member
sp1->field = 10;

// Resource released only when all shared_ptrs are destroyed



// std::weak_ptr: Non-owning observer, breaking circular references

auto owner = std::make_shared<int>(99);

// weak_ptr observes without incrementing count
std::weak_ptr<int> observer = owner;

// Check if resource still exists (owner still valid)
if (!observer.expired()) {
    // Must lock to access safely (creates temporary shared_ptr)
    if (auto safe_access = observer.lock()) {
        int value = *safe_access;
    }
}

owner.reset(); // Resource deleted

// observer.lock() now returns nullptr
